You can multiply using repeated addition (add one number to itself the other number of times):

```c
#include <stdio.h>

int mul_add(int a, int b) {
    int sign = 1;

    if (a < 0) { a = -a; sign = -sign; }
    if (b < 0) { b = -b; sign = -sign; }

    int result = 0;
    while (b > 0) {
        result = result + a;  // only '+'
        b = b - 1;            // uses '-' (see note below)
    }
    return sign * result;
}

int main() {
    int a = 3, b = -5;
    printf("%d\n", mul_add(a, b));  // -15
    return 0;
}
```

